_pending_approvals: dict[
    str,
    tuple[RequireUserConfirmEvent, asyncio.Future[UserConfirmResultEvent]],
] = {}



def _dump(obj: Any) -> Any:
    if obj is None:
        return None
    if hasattr(obj, "model_dump"):
        return obj.model_dump(mode="json") #转json
    return obj


#后续可升级为更优雅的match
def translate(event: Any) -> dict[str, Any] | None:
    """AgentScope 事件 → {event, data}；入站/未知类型返回 None。"""

    if isinstance(event, ReplyStartEvent):
        return {
            "event": "reply.start",
            "data": {
                "session_id": event.session_id,
                "reply_id": event.reply_id,
                "name": event.name,
                "role": event.role,
            },
        }

    if isinstance(event, ReplyEndEvent):
        return {
            "event": "reply.end",
            "data": {
                "session_id": event.session_id,
                "reply_id": event.reply_id,
                "finished_reason": event.finished_reason,
                "error": _dump(event.error),
            },
        }

    if isinstance(event, ModelCallStartEvent):
        return {
            "event": "model.start",
            "data": {
                "reply_id": event.reply_id,
                "model_name": event.model_name,
            },
        }

    if isinstance(event, ModelCallEndEvent):
        return {
            "event": "model.end",
            "data": {
                "reply_id": event.reply_id,
                "input_tokens": event.input_tokens,
                "output_tokens": event.output_tokens,
                "cache_input_tokens": event.cache_input_tokens,
                "cache_creation_input_tokens": event.cache_creation_input_tokens,
                "finished_reason": event.finished_reason,
            },
        }

    if isinstance(event, TextBlockStartEvent):
        return {
            "event": "stream.text.start",
            "data": {
                "reply_id": event.reply_id,
                "block_id": event.block_id,
            },
        }

    if isinstance(event, TextBlockDeltaEvent):
        return {
            "event": "stream.text",
            "data": {
                "reply_id": event.reply_id,
                "block_id": event.block_id,
                "text_delta": event.delta,
            },
        }

    if isinstance(event, TextBlockEndEvent):
        return {
            "event": "stream.text.end",
            "data": {
                "reply_id": event.reply_id,
                "block_id": event.block_id,
            },
        }

    if isinstance(event, ThinkingBlockStartEvent):
        return {
            "event": "stream.thinking.start",
            "data": {
                "reply_id": event.reply_id,
                "block_id": event.block_id,
            },
        }

    if isinstance(event, ThinkingBlockDeltaEvent):
        return {
            "event": "stream.thinking",
            "data": {
                "reply_id": event.reply_id,
                "block_id": event.block_id,
                "text_delta": event.delta,
            },
        }

    if isinstance(event, ThinkingBlockEndEvent):
        return {
            "event": "stream.thinking.end",
            "data": {
                "reply_id": event.reply_id,
                "block_id": event.block_id,
            },
        }

    if isinstance(event, DataBlockStartEvent):
        return {
            "event": "stream.data.start",
            "data": {
                "reply_id": event.reply_id,
                "block_id": event.block_id,
                "media_type": event.media_type,
            },
        }

    if isinstance(event, DataBlockDeltaEvent):
        return {
            "event": "stream.data",
            "data": {
                "reply_id": event.reply_id,
                "block_id": event.block_id,
                "media_type": event.media_type,
                "data": event.data,
            },
        }

    if isinstance(event, DataBlockEndEvent):
        return {
            "event": "stream.data.end",
            "data": {
                "reply_id": event.reply_id,
                "block_id": event.block_id,
            },
        }

    if isinstance(event, HintBlockEvent):
        hint = event.hint
        if isinstance(hint, list):
            hint = [_dump(b) for b in hint]
        return {
            "event": "stream.hint",
            "data": {
                "reply_id": event.reply_id,
                "block_id": event.block_id,
                "source": event.source,
                "hint": hint,
            },
        }

    if isinstance(event, ToolCallStartEvent):
        return {
            "event": "tool.call.start",
            "data": {
                "reply_id": event.reply_id,
                "tool_call_id": event.tool_call_id,
                "name": event.tool_call_name,
            },
        }

    if isinstance(event, ToolCallDeltaEvent):
        return {
            "event": "tool.call.delta",
            "data": {
                "reply_id": event.reply_id,
                "tool_call_id": event.tool_call_id,
                "delta": event.delta,
            },
        }

    if isinstance(event, ToolCallEndEvent):
        return {
            "event": "tool.call.end",
            "data": {
                "reply_id": event.reply_id,
                "tool_call_id": event.tool_call_id,
            },
        }

    if isinstance(event, ToolResultStartEvent):
        return {
            "event": "tool.result.start",
            "data": {
                "reply_id": event.reply_id,
                "tool_call_id": event.tool_call_id,
                "name": event.tool_call_name,
            },
        }

    if isinstance(event, ToolResultTextDeltaEvent):
        return {
            "event": "tool.result.delta",
            "data": {
                "reply_id": event.reply_id,
                "tool_call_id": event.tool_call_id,
                "text_delta": event.delta,
            },
        }

    if isinstance(event, ToolResultDataDeltaEvent):
        return {
            "event": "tool.result.data",
            "data": {
                "reply_id": event.reply_id,
                "tool_call_id": event.tool_call_id,
                "block_id": event.block_id,
                "media_type": event.media_type,
                "data": event.data,
                "url": event.url,
            },
        }

    if isinstance(event, ToolResultEndEvent):
        return {
            "event": "tool.result.end",
            "data": {
                "reply_id": event.reply_id,
                "tool_call_id": event.tool_call_id,
                "state": event.state,
                "metadata": event.metadata,
            },
        }

    if isinstance(event, RequireUserConfirmEvent):
        return {
            "event": "approval.request",
            "data": {
                "approval_request_id": event.reply_id,
                "reply_id": event.reply_id,
                "tool_calls": [_dump(tc) for tc in event.tool_calls],
            },
        }

    return None

def get_config(key: str | None = None) -> dict[str, Any]:
    """读取配置；``key`` 为空则返回三块公开视图。"""

    sections = {
        "model": model_config.get(),
        "permission": permission_config.get(),
        "workspace": {
            "root": workspace_manager.project_root,
            "agent_home": workspace_manager.agent_home,
        },
    }

    if key is None:
        return sections #为空就获取全部的内容。
    if key in sections:
        return {key: sections[key]}
    if key in MODEL_CONFIG_KEYS:
        return {key: sections["model"].get(key)}
    if key in PERMISSION_CONFIG_KEYS:
        return {key: sections["permission"].get(key)}
    if key in ("root", "agent_home"):
        return {key: sections["workspace"].get(key)}

    raise KeyError(f"unknown config key: {key!r}")


def set_config(key: str, value: Any) -> dict[str, Any]:
    """按 KEYS 路由热更新；model/permission 挂载到全部活跃会话。"""
    if key in MODEL_CONFIG_KEYS:
        result = model_config.update(**{key: value})
        for agent in workspace_manager.session_manager.live_agents():
            model_config.update(agent=agent, **{key: value}) #热挂载到活跃会话
        return result

    if key in PERMISSION_CONFIG_KEYS:
        result = permission_config.update(**{key: value})
        for agent in workspace_manager.session_manager.live_agents():
            permission_config.update(agent=agent, **{key: value})
        return result

    raise KeyError(f"unknown config key: {key!r}")


async def stream_chat(text: str, attachments: list[dict] | None = None) -> AsyncIterator[dict[str, Any]]:

    """取（或建）会话 Agent + ``reply_stream``；遇审批则挂起等待 ``respond_approval``。"""

    cid = conversation_id_var.get() or "c-local" #test.py 直调时的兜底
    session = workspace_manager.session_manager

    agent = session.get(cid)
    if agent is None:
        state = session.load_state(cid) or AgentState()
        state.session_id = cid #会话身份只在这里绑定
        agent = await build_agent(workspace_manager, state)
        session.bind(cid, agent)

    snapshot = SnapshotManager(workspace_manager.agent_home, cid, workspace_manager.project_root)
    snapshot.begin_round()

    try:
        blocks: list[TextBlock | DataBlock] = [TextBlock(text=text)]
        for att in attachments or []:
            blocks.append(
                DataBlock(
                    source=Base64Source(
                        data=att["data"],
                        media_type=att["media_type"],
                    ),
                    name=att["name"],
                )
            )
        inputs: Any = UserMsg(name="user", content=blocks)

        while True:

            pending: RequireUserConfirmEvent | None = None

            async for event in agent.reply_stream(inputs):

                if isinstance(event, RequireUserConfirmEvent):
                    pending = event
                    loop = asyncio.get_running_loop()

                    fut: asyncio.Future[UserConfirmResultEvent] = (
                        loop.create_future()

                    )
                    _pending_approvals[event.reply_id] = (event, fut)

                wire = translate(event) #核心转化

                #如果wire为None 则证明底层框架没有这个事件不透传， 或者更改translate进行相关处理
                if wire is not None:
                    yield wire


            if pending is None: #没有请求就继续
                break

            aid = pending.reply_id # = event.reply_id

            try:
                inputs = await _pending_approvals[aid][1]

            finally:
                _pending_approvals.pop(aid, None)

    finally:
        session.save_state(cid, agent.state) #run 终止（含中断/出错）回存会话状态


async def switch_workspace(root: str) -> dict[str, Any]:
    """硬边界变更：换新工作区，旧的关沙箱清会话（磁盘存档原地保留）。"""
    global workspace_manager
    new_ws = WorkspaceManager(root)
    old = workspace_manager
    workspace_manager = new_ws
    await old.close_workspace()
    return {
        "root": new_ws.project_root,
        "agent_home": new_ws.agent_home,
    }


def list_sessions() -> list[dict[str, Any]]:
    """列出所有已持久化的会话，返回元数据列表。"""
    sessions_dir = workspace_manager.session_manager._dir
    result: list[dict[str, Any]] = []
    if not sessions_dir.is_dir():
        return result
    for child in sorted(sessions_dir.iterdir(), key=lambda p: p.stat().st_mtime, reverse=True):
        if not child.is_dir():
            continue
        state_path = child / "state.json"
        meta: dict[str, Any] = {"cid": child.name}
        if state_path.is_file():
            try:
                data = json.loads(state_path.read_text(encoding="utf-8"))
                meta["summary"] = data.get("summary") or ""
                meta["session_id"] = data.get("session_id") or ""
            except (OSError, ValueError):
                meta["summary"] = ""
                meta["session_id"] = ""
            import os
            meta["modified"] = os.path.getmtime(state_path)
        result.append(meta)
    return result


def resume_session(source_cid: str) -> dict[str, Any]:
    """将会话状态从 source_cid 恢复到当前 conversation_id。"""
    cid = conversation_id_var.get() or "c-local"
    session = workspace_manager.session_manager

    source_state = session.load_state(source_cid)
    if source_state is None:
        raise KeyError(f"会话 {source_cid} 不存在")

    session.save_state(cid, source_state)

    # 如果当前 cid 已有 live agent，更新其 state
    live = session.get(cid)
    if live is not None:
        live.state = source_state

    return {"source_cid": source_cid, "target_cid": cid, "resumed": True}


def delete_session(cid: str) -> dict[str, Any]:
    """删除指定会话的持久化文件。"""
    sessions_dir = workspace_manager.session_manager._dir
    target = sessions_dir / cid
    if not target.is_dir():
        raise KeyError(f"会话 {cid} 不存在")
    shutil.rmtree(target)
    return {"cid": cid, "deleted": True}


def respond_approval(
    approval_request_id: str,
    approved: bool,

) -> dict[str, Any]:


    entry = _pending_approvals.get(approval_request_id)
    if entry is None:
        raise KeyError(
            f"no pending approval: {approval_request_id!r}",
        )

    req, fut = entry
    if fut.done():
        raise RuntimeError(
            f"approval already resolved: {approval_request_id!r}",
        )

    results = [
        ConfirmResult(confirmed=approved, tool_call=tc)
        for tc in req.tool_calls
    ]
    fut.set_result(
        UserConfirmResultEvent(
            reply_id=req.reply_id,
            confirm_results=results,
        ),
    )
    return {
        "approval_request_id": approval_request_id,
        "approved": approved,
    }


async def list_skills() -> list[dict[str, Any]]:
    """列出工作区中所有已加载的 skill。"""
    ws, _ = await workspace_manager.ensure_workspace()
    skills = await ws.list_skills()
    return [{"name": s.name, "description": s.description, "dir": s.dir} for s in skills]


async def list_mcp_servers() -> list[dict[str, Any]]:
    """列出所有已连接的 MCP 服务器及其工具数量。"""
    ws, _ = await workspace_manager.ensure_workspace()
    mcps = await ws.list_mcps()
    result = []
    for client in mcps:
        tools = await client.list_tools()
        result.append({
            "name": client.name,
            "type": client.mcp_config.type,
            "tool_count": len(tools),
        })
    return result
